#!/usr/bin/env node
/**
 * Syncs guides release cards, changelog and navbar from git history.
 *
 * Single source of truth: git tags + Conventional Commits, via
 * `scripts/generate-release-notes.mjs --all --json`.
 *
 * Generates:
 *   - guides/src/data/releases.ts   (last N tags, auto-generated, do not hand-edit)
 *   - guides/content/changelog.md   (root CHANGELOG.md + Docusaurus frontmatter)
 *   - guides/docusaurus.config.ts   (Releases navbar dropdown lists all tags)
 *
 * The Docusaurus config cannot import local data (static site constraint), so
 * this script rewrites the config in-place, replacing the marked RELEASES block.
 *
 * Usage:
 *   node scripts/sync-docs-releases.mjs [--limit=8] [--navbar-limit=8] [--check]
 *
 *   --check exits 1 when the generated output differs from what is committed,
 *   for use in CI (`bun run guides:check`).
 *
 * This script runs automatically as part of `bun run guides:build`. After cutting a
 * new release, run `bun run guides:sync` and commit the result (CI enforces it).
 */
import { execFileSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const RELEASES_TS = join(ROOT, "guides", "src", "data", "releases.ts");
const CHANGELOG_SRC = join(ROOT, "CHANGELOG.md");
const CHANGELOG_DST = join(ROOT, "guides", "content", "changelog.md");
const DOCS_CONFIG = join(ROOT, "guides", "docusaurus.config.ts");

const GITHUB_TAGS = "https://github.com/senseikatana/katanakit/releases/tag";

const args = process.argv.slice(2);
const parseLimit = (name, fallback) => {
	const arg = args.find((a) => a.startsWith(`--${name}=`));
	const value = Number.parseInt(arg?.split("=")[1] ?? String(fallback), 10);
	return Number.isNaN(value) || value < 1 ? fallback : value;
};
const LIMIT = parseLimit("limit", 8);
const NAVBAR_LIMIT = parseLimit("navbar-limit", LIMIT);
const CHECK = args.includes("--check");

const run = (script, ...scriptArgs) =>
	execFileSync("node", [join(ROOT, "scripts", script), ...scriptArgs], {
		cwd: ROOT,
		encoding: "utf8",
	});

/** Single-quoted TS string literal, safely escaped. */
function tsString(value) {
	return `\'${value.replace(/\\/g, "\\\\").replace(/'/g, "\\'")}\'`;
}

function formatDate(iso) {
	return new Intl.DateTimeFormat("en-US", {
		month: "long",
		day: "numeric",
		year: "numeric",
	}).format(new Date(`${iso}T00:00:00Z`));
}

function formatItem(item) {
	const scope = item.scope ? `**${item.scope}:** ` : "";
	const breaking = item.breaking ? "**BREAKING** " : "";
	const message = item.message.charAt(0).toUpperCase() + item.message.slice(1);
	return `${breaking}${scope}${message}`;
}

function toCard(release, index) {
	const kind = index === 0 ? "latest" : /^\d+\.0\.0$/.test(release.version) ? "major" : "minor";
	const flat = release.sections.flatMap((section) =>
		section.items.map((item) => ({ section: section.title, text: formatItem(item) })),
	);
	const features = release.sections.find((section) => section.title.startsWith("🚀"));
	const summary =
		features?.items.length > 0
			? formatItem(features.items[0])
			: flat.length > 0
				? flat[0].text
				: `Release ${release.version} — see the release notes for details.`;
	const highlights =
		flat.length > 0
			? flat.slice(0, 6).map((entry) => entry.text)
			: ["See the full release notes on GitHub for details."];

	return {
		version: release.version,
		kind,
		date: formatDate(release.date),
		tag: release.tag,
		summary,
		highlights,
	};
}

function renderReleasesTs(cards) {
	const entries = cards
		.map(
			(card) => `  {
    version: ${tsString(card.version)},
    kind: ${tsString(card.kind)},
    date: ${tsString(card.date)},
    tag: ${tsString(card.tag)},
    summary: ${tsString(card.summary)},
    highlights: [
${card.highlights.map((highlight) => `      ${tsString(highlight)},`).join("\n")}
    ],
  },`,
		)
		.join("\n");
	return `// AUTO-GENERATED by scripts/sync-docs-releases.mjs — do not hand-edit.
// Regenerate with: bun run guides:sync
export type ReleaseKind = 'latest' | 'major' | 'minor';

export interface Release {
  /** Full version label, e.g. "2.15.0". */
  version: string;
  kind: ReleaseKind;
  /** Human-readable date, e.g. "September 13, 2026". */
  date: string;
  /** Git tag backing this release, e.g. "v2.15.0". */
  tag: string;
  /** One or two sentences framing the release. */
  summary: string;
  /** Checklist of what the release brought. */
  highlights: string[];
}

export const releases: Release[] = [
${entries}
];
`;
}

function renderChangelogMd() {
	const source = readFileSync(CHANGELOG_SRC, "utf8").replace(/^# Changelog\n\n/, "");
	return `---
title: Changelog
sidebar_position: 4
description: Release history for KatanaKit JS
---

{/* AUTO-GENERATED by scripts/sync-docs-releases.mjs from CHANGELOG.md — do not hand-edit. */}
{/* Regenerate with: bun run guides:sync */}

# Changelog

${source.trimEnd()}
`;
}

function renderNavbarItems(tags) {
	const items = tags.map(
		(tag) =>
			`\t\t\t\t\t{
						label: ${JSON.stringify(tag)},
						href: \`${GITHUB_TAGS}/${tag}\`,
					},`,
	);
	return `// <RELEASES-NAVBAR-ITEMS> — generated by scripts/sync-docs-releases.mjs
				items: [
${items.join("\n")}
				],
				// </RELEASES-NAVBAR-ITEMS>`;
}

function renderConfig(cards) {
	const source = readFileSync(DOCS_CONFIG, "utf8");
	const tags = cards.slice(0, NAVBAR_LIMIT).map((card) => card.tag);
	const marker = /\/\/ <RELEASES-NAVBAR-ITEMS>[\s\S]*?\/\/ <\/RELEASES-NAVBAR-ITEMS>/;
	if (!marker.test(source)) {
		throw new Error(
			"Missing RELEASES-NAVBAR-ITEMS markers in " + DOCS_CONFIG + "; restore the marker block around the Releases dropdown items.",
		);
	}
	return source.replace(marker, renderNavbarItems(tags));
}

const all = JSON.parse(run("generate-release-notes.mjs", "--all", "--json"));
// Tags with no parseable Conventional Commits carry no card content, skip them.
const cards = all.filter((release) => release.sections.length > 0).slice(0, LIMIT).map(toCard);

const outputs = [
	{ path: RELEASES_TS, content: renderReleasesTs(cards) },
	{ path: CHANGELOG_DST, content: renderChangelogMd() },
	{ path: DOCS_CONFIG, content: renderConfig(cards) },
];

if (CHECK) {
	const drifted = outputs.filter(
		({ path, content }) => readFileSync(path, "utf8") !== content,
	);
	if (drifted.length > 0) {
		for (const { path } of drifted) {
			console.error(`Out of sync: ${path} (run bun run guides:sync)`);
		}
		process.exit(1);
	}
	console.log(`Docs releases in sync (${cards.length} cards).`);
} else {
	for (const { path, content } of outputs) {
		writeFileSync(path, content);
		console.log(`Wrote ${path}`);
	}
}
